# Constants
DEFAULT_VERIFY_BUDGET = 3
_MAX_DETAIL_CHARS = 400

# Gate names order
GATE_NAMES = ("syntax", "build", "smoke", "tests", "telemetry")

# Status constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'

# Dependency Contracts
try:
    from hae.evaluation.artifacts import filter_bundle, is_generated_path, is_malformed_path, sanitize_path, partition_bundle, count_source_files
except ImportError:
    # Minimal stubs for artifacts if not found, matching the contract description
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return False
        if '*' in path or '`' in path:
            return True
        if path != path.strip():
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        path = path.replace('*', '').replace('`', '')
        path = path.strip()
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        return sum(1 for k in bundle if any(k.endswith(s) for s in suffixes))

@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED

@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        ev = self.evaluated_gates
        if not ev:
            return 0.0
        return len(self.passed_gates) / len(ev)

    def summary(self) -> str:
        return f"{len(self.passed_gates)}/{len(self.evaluated_gates)} gates passed"

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [g.__dict__ for g in self.gates],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version
        }

def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    # Regex to find fenced code blocks with optional language and optional filename
    # Pattern: ```[language] [filename]\n(content)\n```
    # We look for lines starting with ``` followed by optional text, then content, then ```
    pattern = r"```(?:\w+)?(?:\s+([^\n]+))?\n(.*?)\n```"
    matches = re.finditer(pattern, text, re.DOTALL)

    bundle = {}
    for match in matches:
        filename = match.group(1)
        content = match.group(2)

        if not filename:
            # If no filename is provided in the fence, we can't reliably map it.
            # In a real scenario, we might guess or skip. Here we skip.
            continue

        # Clean up filename (remove leading/trailing whitespace, quotes)
        filename = filename.strip().strip('"').strip("'")

        # Sanitize path to remove markdown artifacts if any leaked into the filename
        filename = sanitize_path(filename)

        if filename:
            bundle[filename] = content

    return bundle

class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int=60, penalty_per_gate: float=6.25, python_executable: Optional[str]=None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any=None, deliverable_text: str='') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        if workspace:
            try:
                if hasattr(workspace, 'export_bundle'):
                    bundle = workspace.export_bundle()
                elif isinstance(workspace, dict):
                    bundle = workspace
            except Exception:
                bundle = {}

        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)

        return self.verify_bundle(bundle, source='workspace')

    def verify_bundle(self, bundle: Dict[str, str], source: str='bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter out generated and malformed paths
        filtered_bundle = filter_bundle(bundle)

        authored_files = len(filtered_bundle)
        python_files = sum(1 for p in filtered_bundle if p.endswith('.py'))

        if authored_files == 0:
            # Empty workspace fails everything evaluable
            gates = []
            for name in GATE_NAMES:
                gates.append(GateResult(
                    name=name,
                    status=FAILED,
                    method='empty_workspace',
                    detail='No authored files found.'
                ))
            return VerificationReport(
                gates=gates,
                score_penalty=len(GATE_NAMES) * self.penalty_per_gate,
                authored_files=0,
                python_files=0,
                source=source
            )

        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to temp dir
            for path, content in filtered_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=filtered_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]]=None, source: str='directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory for files
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Skip hidden dirs and common generated dirs
                dirs[:] = [d for d in dirs if not d.startswith('.') and d not in ('__pycache__', 'venv', '.venv')]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        authored_files = len(authored)
        python_files = sum(1 for p in authored if p.endswith('.py'))

        gates = []

        # 1. Syntax Gate
        syntax_result = self._check_syntax(workdir, authored)
        gates.append(syntax_result)

        # 2. Build Gate
        build_result = self._check_build(workdir, authored)
        gates.append(build_result)

        # 3. Smoke Gate
        smoke_result = self._check_smoke(workdir, authored)
        gates.append(smoke_result)

        # 4. Tests Gate
        tests_result = self._check_tests(workdir, authored)
        gates.append(tests_result)

        # 5. Telemetry Gate
        telemetry_result = self._check_telemetry(workdir, authored)
        gates.append(telemetry_result)

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _check_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        py_files = [p for p in authored if p.endswith('.py')]
        if not py_files:
            return GateResult(name='syntax', status=FAILED, method='ast_parse', detail='No Python files found.')

        errors = []
        for path in py_files:
            full_path = os.path.join(workdir, path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    source = f.read()
                ast.parse(source)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")
            except Exception as e:
                errors.append(f"{path}: {e}")

        if errors:
            return GateResult(name='syntax', status=FAILED, method='ast_parse', detail='; '.join(errors))
        return GateResult(name='syntax', status=PASSED, method='ast_parse', detail='All Python files parsed successfully.')

    def _check_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(name='build', status=FAILED, method='metadata_check', detail='No packaging metadata found (pyproject.toml, setup.py, or setup.cfg).')

        if has_pyproject:
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(key in data for key in ('project', 'build-system', 'tool')):
                    return GateResult(name='build', status=FAILED, method='toml_validate', detail='pyproject.toml is missing required tables ([project], [build-system], or [tool]).')
            except Exception as e:
                return GateResult(name='build', status=FAILED, method='toml_validate', detail=f'Failed to parse pyproject.toml: {e}')

        # Try pip install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], check=True, capture_output=True, timeout=10)

            # Run pip install -e .
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            if result.returncode != 0:
                return GateResult(name='build', status=FAILED, method='pip_install', detail=f'pip install failed: {result.stderr}')
            return GateResult(name='build', status=PASSED, method='pip_install', detail='Package installed successfully.')
        except FileNotFoundError:
            return GateResult(name='build', status=SKIPPED, method='pip_install', detail='pip not available.')
        except subprocess.TimeoutExpired:
            return GateResult(name='build', status=FAILED, method='pip_install', detail='pip install timed out.')
        except Exception as e:
            return GateResult(name='build', status=FAILED, method='pip_install', detail=f'pip install error: {e}')

    def _check_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        # Find non-test modules
        modules = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            if 'test' in os.path.basename(path).lower():
                continue
            # Convert path to module name
            # Remove .py
            mod_path = path[:-3]
            # Replace / with .
            mod_name = mod_path.replace('/', '.').replace('\\', '.')
            # Handle __init__.py
            if mod_name.endswith('.__init__'):
                mod_name = mod_name[:-9]
            if mod_name:
                modules.append(mod_name)

        if not modules:
            return GateResult(name='smoke', status=FAILED, method='import_check', detail='No importable modules found.')

        # Set up PYTHONPATH
        env = os.environ.copy()
        python_path = env.get('PYTHONPATH', '')
        new_paths = [workdir, os.path.join(workdir, 'src')]
        if python_path:
            env['PYTHONPATH'] = os.pathsep.join(new_paths + [python_path])
        else:
            env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # Try importing each module
        failed_modules = []
        skipped_modules = []

        for mod_name in modules:
            try:
                # Use subprocess to isolate imports
                code = f"import {mod_name}"
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=10
                )
                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package
                        # Simple heuristic: if the module name is not in our authored files, it's likely third-party
                        # But we are importing our own modules. If our module imports a missing third-party, it fails.
                        # The spec says: "If module imports fail solely with ModuleNotFoundError for uninstalled third-party packages... return SKIPPED"
                        # We need to distinguish if the error is from our code or a dependency.
                        # If the error is "No module named 'opentelemetry'", it's third-party.
                        # If the error is "No module named 'my_module'", it's our code.
                        # We can check if the missing module is in our authored files.
                        missing_mod = None
                        for line in stderr.splitlines():
                            if "No module named" in line:
                                # Extract module name
                                parts = line.split("'")
                                if len(parts) > 1:
                                    missing_mod = parts[1]
                                    break
                        if missing_mod and missing_mod not in [m.split('.')[0] for m in modules]:
                            skipped_modules.append(mod_name)
                        else:
                            failed_modules.append(mod_name)
                    else:
                        failed_modules.append(mod_name)
            except Exception:
                failed_modules.append(mod_name)

        if failed_modules:
            return GateResult(name='smoke', status=FAILED, method='import_check', detail=f'Failed to import: {", ".join(failed_modules)}')
        if skipped_modules:
            return GateResult(name='smoke', status=SKIPPED, method='import_check', detail=f'Skipped due to missing dependencies: {", ".join(skipped_modules)}')
        return GateResult(name='smoke', status=PASSED, method='import_check', detail='All modules imported successfully.')

    def _check_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        # Discover test files
        test_files = [p for p in authored if 'test' in os.path.basename(p).lower() and p.endswith('.py')]

        if not test_files:
            return GateResult(name='tests', status=FAILED, method='discover', detail='No test files found.')

        # Set up PYTHONPATH
        env = os.environ.copy()
        python_path = env.get('PYTHONPATH', '')
        new_paths = [workdir, os.path.join(workdir, 'src')]
        if python_path:
            env['PYTHONPATH'] = os.pathsep.join(new_paths + [python_path])
        else:
            env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # Try pytest first
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], check=True, capture_output=True, timeout=10)
            # Run pytest
            result = subprocess.run(
                [self.python_executable, '-m', 'pytest', '-v'],
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            if result.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='pytest', detail='All tests passed.')
            else:
                # Check if it was a collection error due to missing deps
                if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                    return GateResult(name='tests', status=SKIPPED, method='pytest', detail='Tests skipped due to missing dependencies.')
                return GateResult(name='tests', status=FAILED, method='pytest', detail=f'Tests failed: {result.stdout[-500:]}')
        except FileNotFoundError:
            pass # pytest not installed, fallback
        except Exception:
            pass # pytest failed to run, fallback

        # Fallback: stdlib unittest
        # We need to import each test file and collect tests
        # This is complex to do in a single subprocess call robustly.
        # We'll write a small script to run tests.

        script = f'''
